// Shared name-drop database for all interview slide decks.
// Each entry: category, what (one-liner), why (why it matters / interesting fact), alt (alternatives & trade-offs).
// Usage in decks: <span class="nd" data-key="gpipe">GPipe</span> + load this file + tooltip JS.
const NAMEDROPS = {
  // ---------- Parallelism strategies ----------
  "gpipe": { name: "GPipe", category: "Parallelism",
    what: "Google's 2019 pipeline-parallelism library (Huang et al., NeurIPS): split layers across accelerators, split the batch into micro-batches.",
    why: "THE paper to cite for pipeline parallelism in a Google interview. Introduced the all-forward-then-all-backward schedule and popularized re-materialization (activation recomputation).",
    alt: "PipeDream (1F1B schedule, less activation memory), Megatron interleaved pipeline, DeepSeek DualPipe (near-zero bubble)." },
  "pipedream": { name: "PipeDream / 1F1B", category: "Parallelism",
    what: "Microsoft Research + CMU pipeline schedule: each stage alternates one-forward-one-backward instead of all-forwards-first.",
    why: "Caps in-flight activations at ~p micro-batches instead of m, slashing memory vs GPipe at the same bubble fraction. The 1F1B schedule is what Megatron-LM actually ships.",
    alt: "GPipe schedule (simpler, more memory), zero-bubble schedules (ZB-H1, DualPipe) that split backward into grad-of-input vs grad-of-weight." },
  "pipeline-bubble": { name: "Pipeline bubble", category: "Parallelism",
    what: "Idle time at the start/end of a pipelined batch while stages wait for work to arrive or drain.",
    why: "Bubble fraction = (p−1)/(m+p−1) for p stages and m micro-batches — a formula worth reciting. More micro-batches amortize the bubble; more stages inflate it.",
    alt: "Shrink it with more micro-batches, interleaved virtual stages, or zero-bubble schedules; or avoid PP entirely if the model fits." },
  "microbatch": { name: "Micro-batch", category: "Parallelism",
    what: "A slice of the global batch small enough to flow through the pipeline independently; gradients accumulate across micro-batches before the optimizer step.",
    why: "The core GPipe trick: micro-batches are what keep multiple pipeline stages busy simultaneously. Mathematically identical result to one big batch (barring batch-norm).",
    alt: "Gradient accumulation without PP serves the same 'big effective batch' purpose on a single GPU." },
  "megatron": { name: "Megatron-LM", category: "Parallelism",
    what: "NVIDIA's large-model training framework; canonical implementation of tensor parallelism and interleaved pipeline schedules.",
    why: "The Megatron paper (Shoeybi et al., 2019) defined how to split attention heads and MLP blocks across GPUs with just two all-reduces per layer. 'Megatron-style TP' is standard vocabulary.",
    alt: "DeepSpeed (ZeRO-centric), PyTorch FSDP, JAX/XLA GSPMD sharding (the Google-stack answer)." },
  "tensor-parallel": { name: "Tensor parallelism", category: "Parallelism",
    what: "Split individual weight matrices across GPUs; each GPU computes a shard of every layer, synced by all-reduce within the layer.",
    why: "Needs NVLink-class bandwidth because it communicates per layer — so TP stays inside a node (typically ≤8 GPUs) while PP crosses nodes. That TP-inside/PP-across split is the classic cluster layout.",
    alt: "Pipeline parallelism (less bandwidth, has bubbles), FSDP/ZeRO-3 (shards params but gathers them per layer)." },
  "data-parallel": { name: "Data parallelism", category: "Parallelism",
    what: "Replicate the whole model on every GPU, split the batch, all-reduce gradients after backward.",
    why: "The default and simplest scaling axis — until the model + optimizer state no longer fits on one device. Scales batch size, not model size.",
    alt: "ZeRO/FSDP (sharded data parallel), tensor parallel, pipeline parallel — combined as '3D parallelism'." },
  "zero": { name: "ZeRO (DeepSpeed)", category: "Parallelism",
    what: "Microsoft's Zero Redundancy Optimizer: shard optimizer state (stage 1), gradients (2), and parameters (3) across data-parallel ranks.",
    why: "Killed the 'every GPU holds a full Adam state' waste — 16 bytes/param becomes 16/N. Made 100B+ models trainable without exotic parallelism.",
    alt: "PyTorch FSDP is the native reimplementation; Megatron TP+PP is the bandwidth-optimized alternative for dense clusters." },
  "fsdp": { name: "FSDP", category: "Parallelism",
    what: "PyTorch's Fully Sharded Data Parallel — native ZeRO-3: params sharded at rest, all-gathered just-in-time per layer, freed after use.",
    why: "The idiomatic PyTorch answer to 'how do I train a model that doesn't fit?' before reaching for Megatron. FSDP2 (DTensor-based) is current.",
    alt: "DeepSpeed ZeRO, Megatron-LM, JAX pjit/GSPMD on TPUs." },
  "dualpipe": { name: "DualPipe (DeepSeek)", category: "Parallelism",
    what: "DeepSeek-V3's bidirectional pipeline schedule feeding micro-batches from both ends, overlapping compute with communication.",
    why: "Near-zero bubble; part of how DeepSeek trained a 671B MoE for a claimed ~$5.5M of GPU time (2024). Great 'I read recent papers' signal.",
    alt: "Zero Bubble (ZB-H1/ZB-V) schedules, which split backward into B (input grads) and W (weight grads) passes to fill bubbles." },
  "checkpointing": { name: "Activation checkpointing", category: "Memory",
    what: "Discard most activations in forward; recompute them during backward. A.k.a. re-materialization or gradient checkpointing.",
    why: "Trades ~33% extra compute for order-of-magnitude activation-memory savings. GPipe baked it in from day one — essential because pipelining holds many micro-batches in flight.",
    alt: "Keep activations (fast, memory-hungry), offload to CPU/NVMe (DeepSpeed ZeRO-Offload), selective recomputation (only cheap layers)." },
  "grad-accum": { name: "Gradient accumulation", category: "Memory",
    what: "Run several micro-batch forward/backwards, summing gradients, before one optimizer step.",
    why: "Decouples effective batch size from per-step memory. In pipeline parallelism it's implicit — the micro-batches ARE accumulation.",
    alt: "Bigger GPUs, activation checkpointing, or just a smaller batch with adjusted LR." },

  // ---------- Hardware & interconnect ----------
  "nvlink": { name: "NVLink / NVSwitch", category: "Interconnect",
    what: "NVIDIA's GPU-to-GPU interconnect; NVLink 4 gives 900 GB/s per H100, NVSwitch makes it all-to-all within a node.",
    why: "~14× PCIe Gen5 bandwidth — the reason tensor parallelism is feasible inside a node and painful across nodes.",
    alt: "PCIe (cheap, slow), InfiniBand/RoCE between nodes, Google's ICI between TPU chips, AMD Infinity Fabric." },
  "nccl": { name: "NCCL", category: "Interconnect",
    what: "NVIDIA Collective Communications Library — ring/tree implementations of all-reduce, all-gather, reduce-scatter, broadcast, point-to-point.",
    why: "Every PyTorch distributed job rides on it. Ring all-reduce moves 2(N−1)/N × data per GPU regardless of N — bandwidth-optimal, a lovely interview fact.",
    alt: "Gloo (CPU), MPI (HPC heritage), Google's equivalent inside XLA for TPUs." },
  "infiniband": { name: "InfiniBand / RDMA", category: "Interconnect",
    what: "Low-latency cluster fabric (400–800 Gb/s NDR/XDR) with Remote Direct Memory Access — NICs read/write memory without CPU involvement.",
    why: "GPUDirect RDMA lets the NIC DMA straight into GPU HBM, skipping host memory. This is what 'the network is part of the computer' means at cluster scale.",
    alt: "RoCE (RDMA over converged Ethernet — hyperscaler favorite), Google's optical circuit switching for TPU v4 pods." },
  "hbm": { name: "HBM", category: "Hardware",
    what: "High Bandwidth Memory: DRAM dies 3D-stacked next to the GPU die on a silicon interposer. H100: 80 GB HBM3 @ 3.35 TB/s.",
    why: "~30× the bandwidth of CPU DDR5 — the physical reason GPUs can feed their ALUs. Memory bandwidth, not FLOPs, bounds most real kernels.",
    alt: "GDDR (consumer cards, cheaper), on-chip SRAM (Cerebras/Groq take this to extremes), CPU DDR." },
  "tensor-core": { name: "Tensor Core", category: "Hardware",
    what: "Dedicated matrix-multiply-accumulate units: D = A×B + C on small tiles in one instruction.",
    why: "Where ~95% of an H100's advertised FLOPs live. Scalar CUDA-core math is a rounding error for ML workloads.",
    alt: "Google TPU MXU (systolic array), AMD Matrix Cores, Apple AMX, plain SIMD on CPUs." },
  "tpu": { name: "Google TPU", category: "Hardware",
    what: "Google's in-house ML ASIC built around a systolic array — a grid of MACs where data flows through and weights stay put.",
    why: "In a Google interview, contrasting GPU (flexible SIMT) vs TPU (rigid, efficient systolic dataflow) is high-value. Cite the TPU v4 paper (Jouppi et al., ISCA 2023) and its optical circuit switches.",
    alt: "NVIDIA GPUs (ecosystem king), AWS Trainium, Cerebras wafer-scale, Groq LPU (deterministic dataflow for inference)." },

  // ---------- Kernels, compilers, libraries ----------
  "gemm": { name: "GEMM", category: "Kernels",
    what: "GEneral Matrix Multiply — the C = αAB + βC primitive underneath nearly all deep learning compute.",
    why: "O(n³) compute on O(n²) data: the rare op whose arithmetic intensity grows with size, so it can actually saturate the ALUs. Everything (convs, attention) gets lowered to it.",
    alt: "Not really — that's the point. The question is who provides it: cuBLAS, CUTLASS, Triton, or XLA-generated." },
  "cublas": { name: "cuBLAS / cuDNN", category: "Kernels",
    what: "NVIDIA's hand-tuned closed-source libraries: cuBLAS for dense linear algebra, cuDNN for conv/attention/norm primitives.",
    why: "The default fast path under PyTorch. Decades of engineer-years in kernel tuning — the real moat behind CUDA.",
    alt: "CUTLASS (open templates), Triton (write-your-own), rocBLAS/MIOpen (AMD), oneDNN (Intel)." },
  "cutlass": { name: "CUTLASS", category: "Kernels",
    what: "NVIDIA's open-source C++ template library for composing GEMM kernels from tiling primitives (now with the CuTe layout algebra).",
    why: "How you get cuBLAS-class performance with custom epilogues (fused bias+activation). FlashAttention-3 is built on it.",
    alt: "Triton (Python-level, less control), raw CUDA (maximum pain), cuBLAS (no customization)." },
  "triton": { name: "OpenAI Triton", category: "Kernels",
    what: "Python DSL + compiler for writing GPU kernels at the tile level; the compiler handles memory coalescing and scheduling.",
    why: "Powers torch.compile's codegen (TorchInductor). Democratized kernel writing — researchers ship custom fused kernels without CUDA expertise.",
    alt: "CUDA C++ (more control), CUTLASS, Pallas (the JAX/TPU equivalent — Google name-drop!)." },
  "xla": { name: "XLA", category: "Compilers",
    what: "Google's Accelerated Linear Algebra compiler: takes computation graphs (JAX, TF) and emits fused, optimized code for TPUs and GPUs.",
    why: "THE Google compiler name. Does aggressive operator fusion and powers GSPMD — compiler-driven sharding where you annotate arrays and XLA plans the distribution.",
    alt: "torch.compile/Inductor (PyTorch world), TVM, MLIR (the infra XLA itself is migrating onto — 'OpenXLA' umbrella)." },
  "flashattention": { name: "FlashAttention", category: "Kernels",
    what: "Tri Dao's IO-aware attention kernel (2022): tile the computation so the N×N attention matrix never materializes in HBM.",
    why: "The canonical case study that attention is memory-bound, not compute-bound. Exact same math, 2–4× faster, O(N) memory — purely from respecting the memory hierarchy.",
    alt: "Standard attention (HBM round-trips), xFormers memory-efficient attention, FlashAttention-2/3 (better parallelism, FP8 on Hopper)." },
  "kernel-fusion": { name: "Kernel fusion", category: "Kernels",
    what: "Combine consecutive ops into one kernel so intermediates stay in registers/shared memory instead of round-tripping through HBM.",
    why: "The #1 remedy for memory-bound and overhead-bound workloads. What XLA and torch.compile mostly do for a living.",
    alt: "CUDA Graphs (fixes launch overhead, not data movement), bigger batches, hand-fused kernels." },

  // ---------- Collectives & communication theory ----------
  "all-reduce": { name: "All-reduce", category: "Collectives",
    what: "Every rank contributes a tensor; all ranks end with the element-wise reduction (usually sum) of everyone's tensor. Equivalent to reduce-scatter followed by all-gather.",
    why: "The workhorse of distributed training: gradient averaging in data parallelism, activation sums in tensor parallelism. NOT a model op — it's inter-GPU communication (contrast with pooling, which aggregates inside one tensor).",
    alt: "Reduce (one rank gets result), reduce-scatter + all-gather (same bytes, exposes the halves for overlap/sharding), all-to-all (MoE routing)." },
  "reduce-scatter": { name: "Reduce-scatter / All-gather", category: "Collectives",
    what: "Reduce-scatter: everyone sums, each rank keeps 1/N of the result. All-gather: each rank's shard is copied to everyone. Composed back-to-back they ARE an all-reduce.",
    why: "The decomposition that powers ZeRO/FSDP (reduce-scatter grads, all-gather params) and Megatron sequence parallelism. Saying 'all-reduce = reduce-scatter + all-gather' is a reliable interview flex.",
    alt: "Plain all-reduce when you don't need the sharded intermediate; broadcast/gather for one-to-many patterns." },
  "alpha-beta": { name: "α-β cost model", category: "Theory",
    what: "Message cost = α + β·n: α is per-message latency (startup), β is per-byte transfer time, n is bytes. The standard tool for analyzing collectives.",
    why: "Explains algorithm choice: ring all-reduce costs ≈ 2(p−1)α + 2((p−1)/p)βn — bandwidth-optimal but latency linear in p; tree algorithms give α·log p latency but worse bandwidth. Pipelining a binary-tree broadcast turns O((α+βn)log p) into O(α·log p + βn) because chunks stream instead of paying log p per byte.",
    alt: "LogP / LogGP models (add overhead & gap parameters) for more fidelity." },
  "gspmd": { name: "GSPMD", category: "Compilers",
    what: "Google's compiler-based sharding in XLA: annotate a few arrays with sharding specs; the compiler propagates them and inserts all the collectives for you.",
    why: "The Google-stack answer to Megatron: instead of hand-writing parallel layers, JAX's jit + sharding annotations let XLA plan TP/DP/PP-like distributions automatically. Cite Xu et al., 2021.",
    alt: "Manual Megatron-style parallel layers (PyTorch world), DTensor (PyTorch's sharding abstraction catching up to this idea)." },
  "sequence-parallel": { name: "Sequence parallelism", category: "Parallelism",
    what: "Megatron extension: in the regions between TP blocks (LayerNorm, dropout), shard activations along the sequence dimension; swap each all-reduce for reduce-scatter + all-gather.",
    why: "Same communication bytes, but activation memory for those regions drops by the TP degree — removed the last unsharded activations in Megatron (Korthikanti et al., 2022).",
    alt: "Plain TP (replicated norms/dropout), Ring Attention / context parallelism for extreme sequence lengths." },

  // ---------- Inference ----------
  "vllm": { name: "vLLM / PagedAttention", category: "Inference",
    what: "Open-source serving engine; PagedAttention manages KV-cache in fixed-size blocks like virtual-memory pages.",
    why: "Killed KV-cache fragmentation → 2–4× throughput via denser batching. Great example of OS ideas (paging!) crossing into ML systems — interviewers love that bridge.",
    alt: "TensorRT-LLM (NVIDIA, peak perf), SGLang (RadixAttention prefix caching), TGI (Hugging Face)." },
  "kv-cache": { name: "KV cache", category: "Inference",
    what: "Stored attention keys/values for all previous tokens so decoding each new token is O(context) instead of O(context²).",
    why: "Dominates inference memory at long context — often bigger than the weights. Why GQA/MQA, quantized KV, and PagedAttention exist.",
    alt: "Recompute (absurd), sliding-window attention, MLA (DeepSeek's latent compression of KV)." },

  // ---------- Architecture ----------
  "gqa": { name: "GQA / MQA", category: "Architecture",
    what: "Grouped-Query / Multi-Query Attention: many query heads share a smaller set of K/V heads (MQA: all share one; GQA: share in groups).",
    why: "Shrinks the KV cache by the sharing factor — Llama-70B uses 64 Q heads but only 8 KV heads → 8× smaller cache, nearly free quality-wise. MQA is a Noam Shazeer solo paper (2019); GQA is the Google follow-up (Ainslie et al., 2023).",
    alt: "Full multi-head attention (biggest cache), MLA (DeepSeek's low-rank KV compression, even smaller), sliding-window attention." },
  "rope": { name: "RoPE", category: "Architecture",
    what: "Rotary Position Embedding (Su et al., 2021): rotate each Q/K pair by a position-dependent angle; dot products then depend only on relative position.",
    why: "Won the positional-encoding wars — used by Llama, Qwen, Gemma, DeepSeek. Elegant hook: rotation is applied at attention time to Q and K only, no learned position parameters at all.",
    alt: "Learned absolute embeddings (GPT-2), sinusoidal (original Transformer), ALiBi (linear distance penalty — trains short, runs long), NoPE." },
  "yarn": { name: "YaRN / NTK scaling", category: "Architecture",
    what: "Context-extension methods that rescale RoPE frequencies so a model trained at 4k positions can run at 128k without retraining from scratch.",
    why: "The standard answer to 'how do models get long context cheaply?' — interpolate/rescale rotary frequencies (position interpolation → NTK-aware → YaRN), then lightly fine-tune.",
    alt: "Train long from scratch (expensive), ALiBi (extrapolates natively), Ring Attention (distribute the sequence itself)." },
  "sliding-window": { name: "Sliding-window attention", category: "Architecture",
    what: "Each token attends only to the last w tokens; receptive field still grows with depth (layer L sees ~L·w back).",
    why: "Caps attention cost and KV cache at O(n·w) instead of O(n²). Mistral-7B shipped it (w=4096); Gemma mixes sliding and global layers.",
    alt: "Full attention (exact, quadratic), dilated/sparse patterns (Longformer, BigBird), linear attention (Mamba/SSMs as the radical alternative)." },
  "moe": { name: "Mixture of Experts", category: "Architecture",
    what: "Replace the dense MLP with N expert MLPs plus a router that sends each token to its top-k experts (k=1–2 typical).",
    why: "Decouples parameter count from per-token FLOPs: DeepSeek-V3 is 671B params but only ~37B active per token. Lineage: Shazeer's sparsely-gated MoE (2017) → Google's Switch Transformer (k=1) → Mixtral → DeepSeek.",
    alt: "Dense models (simpler, better per-param), fine-grained + shared experts (DeepSeekMoE). Costs: all-to-all communication, load-balancing auxiliary losses, router instability." },
  "chinchilla": { name: "Chinchilla / 6ND", category: "Theory",
    what: "Training compute ≈ 6·N·D FLOPs (N params, D tokens: 2ND forward + 4ND backward). Chinchilla scaling (DeepMind, 2022): compute-optimal D ≈ 20·N.",
    why: "The two estimation formulas behind every 'how long would this take to train?' question. Llama-3-70B at 15T tokens ≈ 6·70e9·15e12 ≈ 6.3e24 FLOPs — divide by cluster FLOP/s for wall-clock.",
    alt: "Kaplan scaling laws (the earlier, param-heavy fit), inference-aware scaling (train smaller models longer — why Llama overtrains past Chinchilla-optimal)." },

  // ---------- Retrieval & RecSys ----------
  "two-tower": { name: "Two-Tower model", category: "Retrieval & RecSys",
    what: "Retrieval architecture: a user tower and an item tower each map their inputs to embeddings in a shared space; relevance = dot product (or cosine).",
    why: "The backbone of Google/YouTube-scale retrieval (cite Covington et al. 2016, YouTube RecSys; Yi et al. 2019 for the two-tower + sampled-softmax formulation). Key property: towers decouple at serving — item embeddings precomputed into an ANN index, user embedding computed per request.",
    alt: "Single-tower / cross-attention rankers (more accurate, can't be indexed — used for the RANKING stage after retrieval), matrix factorization (the ancestor), generative retrieval (emerging)." },
  "ann": { name: "ANN / ScaNN", category: "Retrieval & RecSys",
    what: "Approximate Nearest Neighbor search: find the top-k closest embeddings among millions–billions without exact scan. ScaNN is Google's library (anisotropic quantization); FAISS (Meta) and HNSW (graph-based) are the other big names.",
    why: "Turns O(N·d) retrieval into ~O(log N)-ish. The L5-grade operational point: indexes are hard to mutate, so production systems pair a batch-rebuilt main index with a small brute-force fresh buffer for new items, merged at query time.",
    alt: "Exact brute force (fine to ~1M vectors on GPU), IVF-PQ (FAISS quantization), HNSW (fast, memory-hungry), ScaNN (Google's, SOAR-enhanced); vector DBs (Vertex AI Vector Search, Pinecone) wrap these." },
  "sampled-softmax": { name: "Sampled softmax / in-batch negatives", category: "Retrieval & RecSys",
    what: "Training trick for retrieval: full softmax over millions of items is infeasible, so approximate it — sample negatives, or reuse the other items in the batch as negatives.",
    why: "In-batch negatives are nearly free compute-wise but oversample popular items as negatives → apply logQ correction (subtract log of sampling probability from logits). Knowing the correction is the senior tell.",
    alt: "NCE, hard-negative mining (mine near-misses from the ANN index itself), contrastive losses (InfoNCE — same family as CLIP's)." },
  "funnel": { name: "Retrieval → ranking funnel", category: "Retrieval & RecSys",
    what: "The universal RecSys/search shape: billions of items → cheap retrieval picks thousands → a heavy ranker scores hundreds → re-ranking/policy picks the final dozen.",
    why: "Pure cost arithmetic: you cannot run a 100ms cross-attention ranker on 10⁹ items, but you CAN run a dot product against a precomputed index. Each stage trades recall for precision at rising cost-per-item. Framing any RecSys design answer around the funnel is table stakes at Google.",
    alt: "Single-stage exact scoring (only for tiny corpora), generative retrieval (model emits item IDs directly — research-stage)." },
  "wide-deep": { name: "Wide & Deep / DLRM", category: "Retrieval & RecSys",
    what: "Ranking-stage architectures: Wide & Deep (Google, 2016) combines memorized cross-features with a deep tower; DLRM (Meta) is embedding tables + feature interactions + MLP.",
    why: "The ranking stage is where cross-features (user × item interactions) live — exactly what two-tower models can't express (towers only meet at the dot product). Also a hardware story: production embedding tables reach terabytes, so they're sharded across devices — model parallelism for memory, not compute.",
    alt: "GBDTs (still strong for tabular ranking), DCN / DCNv2 (Google's learned feature crosses), transformer-based rankers." },
  "recsys-metrics": { name: "Recall@k / NDCG / online A/B", category: "Retrieval & RecSys",
    what: "Offline: recall@k for the retrieval stage (did the good items make the candidate set?), NDCG/AUC for ranking. Online: CTR, engagement, retention via A/B experiments.",
    why: "The senior move is naming the offline↔online gap: offline gains routinely fail to ship because of position bias, feedback loops (the model trains on its own recommendations), and popularity skew. Say 'we'd validate with an A/B before trusting the offline lift.'",
    alt: "Counterfactual/off-policy evaluation (IPS) when A/B tests are too slow or risky; interleaving for sensitive ranking comparisons." },
  "vectorization": { name: "Vectorization (NumPy)", category: "Coding craft",
    what: "Express array math as whole-array operations (broadcasting, ufuncs) instead of Python loops: weights = np.exp(-lam * (now - timestamps)).",
    why: "Python-level loops are an overhead-bound regime — each element pays interpreter + dispatch cost; vectorized ops run in C over contiguous memory (SIMD on CPU, kernels on GPU). In interviews, writing the vectorized form FIRST is expected at L5.",
    alt: "numba/Cython when logic truly can't vectorize, torch/JAX ops (same idea, GPU-backed), einsum for anything multi-axis." },

  // ---------- Quantization & compression ----------
  "awq": { name: "AWQ", category: "Quantization",
    what: "Activation-aware Weight Quantization: identify the ~1% most salient weight channels (by activation magnitude, not weight magnitude) and protect them via per-channel scaling before quantizing everything to INT4.",
    why: "Minimal perplexity loss from post-training quantization (PTQ) with no retraining — and unlike mixed-precision schemes, the result is hardware-friendly uniform INT4. MLSys 2024 best paper (Lin et al., MIT Han Lab).",
    alt: "GPTQ (Hessian-based error compensation), round-to-nearest (the baseline that breaks at 4-bit), QuaRot/SpinQuant (rotation-based outlier removal — the newer wave)." },
  "gptq": { name: "GPTQ", category: "Quantization",
    what: "Second-order post-training quantization: quantize weights one column at a time, using (approximate) Hessian information to adjust the remaining unquantized weights and compensate the error.",
    why: "Made accurate 4-bit weight compression of giant models practical (descends from LeCun-era Optimal Brain Surgeon ideas — a lovely lineage to cite). The default engine behind many INT4 checkpoints on Hugging Face.",
    alt: "AWQ (activation-aware scaling, often more robust), NF4/bitsandbytes (QLoRA's format), HQQ (calibration-free)." },
  "smoothquant": { name: "SmoothQuant", category: "Quantization",
    what: "Migrates quantization difficulty from activations to weights: divide activations by a per-channel scale s, multiply the corresponding weight columns by s — mathematically identical network, much flatter activation distribution.",
    why: "Solves the outlier-channel problem: a few activation channels in LLMs are ~100× larger than the rest, wrecking INT8 activation quantization. Smoothing enables full W8A8 — weights AND activations in INT8 — which unlocks INT8 tensor-core matmuls, not just memory savings.",
    alt: "LLM.int8() (keep outlier channels in FP16 via decomposition), weight-only quant (sidesteps activations entirely, but matmul stays FP16), rotation methods (QuaRot)." },
  "fp8": { name: "FP8 (E4M3 / E5M2)", category: "Quantization",
    what: "8-bit floating point, two flavors: E4M3 (4 exponent, 3 mantissa bits — more precision) and E5M2 (5 exponent, 2 mantissa — more dynamic range).",
    why: "Native on Hopper/Blackwell tensor cores: ~2× FP16 throughput and half the memory. Standard assignment: E4M3 for weights & activations (forward), E5M2 for gradients (backward — gradients need range, not precision). The Transformer Engine manages per-tensor scaling factors dynamically.",
    alt: "INT8 (cheaper silicon, needs calibration), BF16 (the safe default), FP4/NVFP4 + microscaling (MX) formats on Blackwell — block-level shared exponents." },
  "gguf": { name: "GGUF / llama.cpp", category: "Quantization",
    what: "The llama.cpp ecosystem: a single-file model format (GGUF) plus a C/C++ runtime with block-wise 'K-quants' (Q4_K_M etc.) that runs quantized LLMs on CPUs, Apple Silicon, and consumer GPUs.",
    why: "The de facto standard for local/edge inference — memory-mapped weights, partial GPU offload, no Python stack. Knowing it signals you understand deployment beyond the datacenter.",
    alt: "Ollama (wraps llama.cpp), MLX (Apple), ONNX Runtime / ExecuTorch (mobile-first), TensorRT-LLM (datacenter opposite extreme)." },
  "lora": { name: "LoRA / QLoRA", category: "Quantization",
    what: "Low-Rank Adaptation: freeze base weights W, train only a low-rank update ΔW = B·A (rank r ≈ 8–64); at inference, merge or hot-swap adapters. QLoRA backpropagates through a 4-bit NF4-quantized base model with double quantization and paged optimizers.",
    why: "Collapsed fine-tuning VRAM from ~16 bytes/param to ~1 byte/param-ish — a 70B fine-tune fits on one 48 GB GPU with QLoRA. Serving bonus: one base model + many cheap adapters (multi-tenant LoRA serving, S-LoRA/vLLM).",
    alt: "Full fine-tuning (best quality, brutal memory), DoRA/rsLoRA (refinements), prefix/prompt tuning (lighter, weaker), RL-based post-training (different axis entirely)." },

  // ---------- Serving systems ----------
  "disagg": { name: "Prefill-decode disaggregation", category: "Serving",
    what: "Run prefill and decode on separate hardware pools: prefill nodes optimized for compute throughput (TTFT), decode nodes for memory bandwidth (TPOT); KV cache is shipped between them.",
    why: "Stops compute-heavy prefills from stalling latency-sensitive decode steps — the main p99 tail-latency killer in colocated serving. Cite Splitwise (Microsoft) and DistServe (2024); NVIDIA Dynamo productionizes it.",
    alt: "Colocated serving + chunked prefill (simpler, one pool), priority schedulers. Trade-off: disaggregation pays KV-transfer bandwidth between pools." },
  "radix": { name: "RadixAttention / SGLang", category: "Serving",
    what: "Automatic prefix caching: organize KV-cache blocks in a radix tree keyed by token prefixes, so any request sharing a prefix (system prompt, few-shot examples, agent tree) reuses the cached KV instantly.",
    why: "Cuts TTFT to near zero for repeated prefixes — transformative for multi-turn chat and agent workloads where 90% of the prompt is shared. The headline feature of SGLang (LMSYS).",
    alt: "vLLM's hash-based prefix caching, provider-level prompt caching APIs (Anthropic/OpenAI/Gemini), manual KV reuse." },
  "continuous-batching": { name: "Continuous batching", category: "Serving",
    what: "Iteration-level scheduling: compose the batch fresh at every decode step rather than per request — when one sequence finishes, another's prefill or decode slots in immediately.",
    why: "Eliminates padding waste and head-of-line blocking from static batching; the single biggest throughput win in LLM serving (2–10×). Cite Orca (OSDI 2022) — the paper that introduced it; every modern engine (vLLM, TRT-LLM 'in-flight batching', SGLang) implements it.",
    alt: "Static/request-level batching (the strawman), dynamic batching with timeouts (classic Triton-style, fine for non-autoregressive models)." },
  "speculative": { name: "Speculative decoding", category: "Serving",
    what: "A small draft model proposes k tokens; the big target model verifies all k in ONE parallel forward pass; rejection sampling keeps the output distribution exactly the target model's.",
    why: "2–2.5× decode speedup with provably unchanged outputs — it converts spare compute into bandwidth relief (one weight-read validates k tokens). Cite Leviathan et al. 2023 (Google) and Chen et al. 2023 (DeepMind) — both Google-family papers.",
    alt: "Medusa (extra decoding heads, no draft model), EAGLE (feature-level drafting), n-gram/prompt lookup (free for copy-heavy tasks)." },
  "trt-llm": { name: "TensorRT-LLM", category: "Serving",
    what: "NVIDIA's serving stack: compiled engines, hand-tuned kernels, in-flight batching, paged KV, FP8/FP4 support, tight Hopper/Blackwell integration.",
    why: "The peak-performance pole of the serving spectrum — what you deploy when you own the hardware and want every last token/sec. Trade-off: engine compilation per model/shape, NVIDIA-only, less hackable.",
    alt: "vLLM (open, flexible, the default), SGLang (prefix-caching king), llama.cpp (edge). Spectrum: TRT-LLM = max perf, vLLM = max ecosystem, GGUF = max portability." },
  "ray-serve": { name: "Ray Serve", category: "Serving",
    what: "Python-native serving/orchestration on Ray: compose embedders, retrievers, guardrails, and LLM engines as a graph of autoscaling deployments across a cluster.",
    why: "The orchestration layer ABOVE engines like vLLM (which it commonly wraps) — the answer to 'how do the pieces of the pipeline talk?' in a system-design round. Anyscale's production story.",
    alt: "Kubernetes + KServe, NVIDIA Triton (ensembles), modal/beam-style serverless GPU, hand-rolled FastAPI (fine until autoscaling)." },
  "chunked-prefill": { name: "Chunked prefill", category: "Serving",
    what: "Split a long prompt's prefill into chunks and interleave them with ongoing decode steps in the same batch, instead of letting one giant prefill monopolize the GPU.",
    why: "Protects TPOT from multi-second freezes when someone pastes a 100-page document — the colocated-serving answer to the same problem disaggregation solves with separate pools. A.k.a. DeepSpeed-FastGen's 'Dynamic SplitFuse'; on by default in modern vLLM.",
    alt: "Prefill-decode disaggregation (separate hardware), strict priority scheduling, prompt-length caps (the product cop-out)." },

  // ---------- RAG & vector search ----------
  "hybrid-search": { name: "Hybrid search (sparse + dense)", category: "RAG & Vector Search",
    what: "Run lexical retrieval (BM25/TF-IDF) and dense ANN retrieval in parallel, then fuse results — typically with Reciprocal Rank Fusion (RRF).",
    why: "Dense catches semantics (synonyms, paraphrase); sparse guarantees exact matches for keywords, SKUs, names, and rare terms where embeddings are weakest. Saying 'RRF' and 'BM25 for proper nouns' covers the two senior tells.",
    alt: "Dense-only (fails on exact identifiers), sparse-only (fails on meaning), learned sparse (SPLADE — neural term weights in an inverted index)." },
  "colbert": { name: "ColBERT / late interaction", category: "RAG & Vector Search",
    what: "Keep one embedding PER TOKEN instead of one per document; score query-document pairs with MaxSim (each query token takes its best-matching document token, sum).",
    why: "The middle of the accuracy/cost spectrum: near-cross-encoder quality while documents stay precomputable and indexable. Token-level matching survives the 'single vector squashes a whole doc' information loss.",
    alt: "Bi-encoder single-vector (cheapest), cross-encoder (most accurate, not indexable), SPLADE (sparse cousin). Cost: ~2 orders of magnitude more storage than single-vector." },
  "cross-encoder": { name: "Rerankers / cross-encoders", category: "RAG & Vector Search",
    what: "Feed (query, document) jointly through one transformer with full cross-attention; output a relevance score. Run on only the top-N (~100) candidates from cheap retrieval.",
    why: "The RAG version of the RecSys funnel: bi-encoder for recall, cross-encoder for precision. Catches negation, conditionals, and fine distinctions that dot products structurally cannot express.",
    alt: "ColBERT (cheaper late interaction), LLM-as-reranker (listwise prompting — expensive, strong), no reranker (acceptable when the generator is robust to noisy context)." },
  "hnsw": { name: "HNSW", category: "RAG & Vector Search",
    what: "Hierarchical Navigable Small World: a multi-layer proximity graph (skip-list-like); search greedily descends from sparse top layers to the dense base layer.",
    why: "The default index in most vector DBs (Qdrant, Milvus, Weaviate, pgvector) — excellent recall/latency with no training step. Costs: high memory (graph edges + full vectors) and awkward deletes/updates.",
    alt: "IVF-PQ (compressed, cheaper RAM), ScaNN (quantization-first), DiskANN (SSD-resident graphs for billion-scale on one box)." },
  "scann": { name: "ScaNN", category: "RAG & Vector Search",
    what: "Google's vector-search library: anisotropic vector quantization + SIMD-optimized scoring + partitioning; SOAR (2023) added spilled assignments for robustness.",
    why: "THE Google name in vector search (powers Vertex AI Vector Search). Beats vanilla PQ on the recall/latency curve because its loss function optimizes what retrieval cares about — ranking by inner product — not reconstruction error.",
    alt: "FAISS (Meta's toolbox), HNSW (graph-based), DiskANN (Microsoft). Cite Guo et al., ICML 2020." },
  "anisotropic": { name: "Anisotropic quantization", category: "RAG & Vector Search",
    what: "Quantize vectors with a direction-aware loss: penalize error components parallel to the vector (which flip inner-product rankings) more than orthogonal ones.",
    why: "The insight inside ScaNN: standard PQ minimizes reconstruction error uniformly, but retrieval only cares about errors that change the ranking. Weighting the ranking-relevant direction preserves recall at the same compression.",
    alt: "Uniform PQ (the baseline it beats), OPQ (rotation-optimized PQ), scalar/binary quantization (cruder, cheaper)." },
  "chunking": { name: "Chunking strategies & drift", category: "RAG & Vector Search",
    what: "How raw documents are split for embedding (fixed-size, recursive-character, semantic, layout-aware) plus lifecycle management of stale chunks as the knowledge base changes.",
    why: "Garbage-in-garbage-out: chunking errors cap RAG quality no matter the LLM. Senior tells: overlap windows, parent-document retrieval (embed small, return big), metadata filters, and re-embedding/invalidation on source updates — the RAG twin of the ANN freshness problem.",
    alt: "Late chunking (embed whole doc, pool per chunk), GraphRAG (extract entities/relations instead), long-context stuffing (viable but expensive and recency-biased)." },
  "self-rag": { name: "Self-RAG / CRAG", category: "RAG & Vector Search",
    what: "Agentic RAG loops: grade whether retrieved context is actually relevant, re-query or fall back to web search when it isn't, and critique/verify the generated answer against sources.",
    why: "Moves RAG from a static lookup to a fault-tolerant pipeline — the answer to 'what if retrieval returns junk?' in a system-design round. CRAG's retrieval evaluator + corrective actions is the cleanest version to describe.",
    alt: "Plain RAG (retrieve-once), query rewriting/HyDE (fix the query side), GraphRAG (fix the index side), full agentic search loops." },

  // ---------- Frameworks & ML infrastructure ----------
  "pytorch": { name: "PyTorch", category: "Frameworks & Infra",
    what: "Eager-first deep learning framework (define-by-run autograd); torch.compile (2.0) added graph capture → TorchInductor → Triton-generated kernels for compiled speed without losing eager ergonomics.",
    why: "The research default (~90% of papers) and now a production default too. Know the stack: nn.Module → autograd → dispatcher → ATen kernels; distributed via DDP/FSDP on NCCL. Governance note: Linux Foundation, Meta-born.",
    alt: "JAX (functional, compiler-first), TensorFlow (legacy production estates), Keras 3 (frontend over all three)." },
  "jax": { name: "JAX", category: "Frameworks & Infra",
    what: "Google's functional framework: pure functions transformed composably — grad (autodiff), jit (XLA compile), vmap (auto-batching), pmap/shard_map (SPMD parallelism). NumPy API, immutable arrays, explicit PRNG keys.",
    why: "THE framework to know for a Google interview: it's how TPUs are programmed (DeepMind + Google research run on it; Gemini trained on JAX+TPU). The mental model: 'NumPy + composable function transformations + XLA'. Sharding via GSPMD annotations instead of hand-written parallel layers.",
    alt: "PyTorch (imperative, bigger ecosystem), Flax/Haiku (the NN layers on top of JAX), Pallas (JAX's kernel DSL, the Triton analog)." },
  "tensorflow": { name: "TensorFlow", category: "Frameworks & Infra",
    what: "Google's original production framework: graph-first (TF1) → eager + tf.function (TF2); the ecosystem is the point — TF Serving, TFLite (mobile/edge), TFX (pipelines), TF.js.",
    why: "Fading for research but entrenched in production estates — and it's Google's deployment lineage (TFX papers describe Google's internal ML pipelines). Interview framing: 'TF for existing production + edge, JAX for new Google-stack work, PyTorch everywhere else' shows ecosystem judgment, not tribalism.",
    alt: "PyTorch + torch.compile, JAX, ONNX Runtime (the neutral deployment escape hatch)." },
  "triton-server": { name: "NVIDIA Triton Inference Server", category: "Frameworks & Infra",
    what: "Multi-framework model server: serves TensorRT/PyTorch/ONNX/Python backends behind one gRPC/HTTP endpoint, with dynamic batching, concurrent model execution, and model ensembles.",
    why: "THE disambiguation trap: NVIDIA Triton (inference SERVER) ≠ OpenAI Triton (kernel COMPILER/DSL). Saying 'which Triton?' when it comes up is a free senior point. Triton Server is the general-model answer; vLLM/TRT-LLM are the LLM-specialized answer (TRT-LLM often runs AS a Triton backend).",
    alt: "TorchServe (simpler, PyTorch-only), Ray Serve (Python-native composition), KServe (Kubernetes-native), BentoML." },
  "ray": { name: "Ray", category: "Frameworks & Infra",
    what: "Distributed Python substrate: @ray.remote turns functions into tasks and classes into actors over a cluster, with an object store for zero-copy data sharing. Libraries on top: Ray Train, Tune (HPO), Data, Serve, RLlib.",
    why: "The 'how do I scale arbitrary Python?' answer that doesn't require rewriting into Spark. Used by OpenAI for training orchestration and by vLLM for multi-node serving. Tasks-vs-actors (stateless vs stateful) is the one concept to explain crisply.",
    alt: "Dask (dataframe-centric), Spark (ETL heritage, JVM), Kubernetes Jobs + custom glue (what Ray abstracts away), slurm (HPC heritage)." },
  "kubeflow": { name: "Kubeflow / ML pipelines", category: "Frameworks & Infra",
    what: "Kubernetes-native ML platform: Pipelines (DAGs of containerized steps), Katib (HPO), KServe (serving), notebooks. Each pipeline step is a container; the DAG is versioned and reproducible.",
    why: "The canonical training pipeline to recite: data validation → transform → train → evaluate → (gate) → register → deploy, with lineage tracked. Google's managed flavor is Vertex AI Pipelines (runs KFP definitions) — the right name to drop in a Google interview; TFX is the Google-internal ancestor.",
    alt: "Vertex AI Pipelines (managed, Google), Airflow (general orchestration, not ML-aware), Metaflow (Netflix, Pythonic), Dagster/Prefect (data-eng flavored)." },
  "vector-db": { name: "Vector databases", category: "Frameworks & Infra",
    what: "Databases whose primary index is ANN over embeddings (HNSW/IVF under the hood) plus metadata filtering, CRUD, and replication: Pinecone (managed), Qdrant/Milvus/Weaviate (OSS), pgvector (Postgres extension), Vertex AI Vector Search (Google, ScaNN-backed).",
    why: "The design judgment interviewers probe: pgvector when vectors are a feature of an existing relational app (one database, transactions, joins); a dedicated vector DB when scale/filtering/replication demand it; a raw library (FAISS) when you control the whole serving path. Don't default to new infrastructure.",
    alt: "Elasticsearch/OpenSearch (hybrid search built-in), raw FAISS/ScaNN + your own service, DuckDB-VSS (analytics-local)." },
  "mlops": { name: "MLOps: tracking, registry, drift", category: "Frameworks & Infra",
    what: "The operational layer: experiment tracking (MLflow, Weights & Biases), model registry (versioned, stage-gated artifacts), feature stores (Feast, Vertex), and production monitoring for data/prediction drift.",
    why: "Interview one-liner: 'models degrade silently — the world drifts, the model doesn't.' Monitoring compares live feature distributions vs training (PSI/KL), tracks proxy metrics when labels lag, and triggers retraining. Training/serving skew (features computed differently offline vs online) is the classic bug a feature store exists to kill.",
    alt: "Vertex AI Model Registry + Monitoring (the Google-managed stack), SageMaker (AWS), hand-rolled (how it always starts, and why it breaks)." },

  // ---------- Algorithms: dynamic programming ----------
  "memoization": { name: "Memoization vs tabulation", category: "Algorithms: DP",
    what: "Two ways to reuse subproblem answers. Memoization (top-down): write the plain recursion, cache results in a dict — compute lazily on first request. Tabulation (bottom-up): fill a table from base cases upward in a loop.",
    why: "Same asymptotic complexity; different ergonomics. Memoization is easier to derive (it IS the recursion) and only touches needed states; tabulation avoids recursion-depth limits (Python's ~1000!) and enables space optimization (keep only the last row/two variables). Interview move: derive top-down, then convert.",
    alt: "Plain recursion (exponential when subproblems overlap), divide & conquer (no overlap, so no caching needed)." },
  "optimal-substructure": { name: "Optimal substructure + overlapping subproblems", category: "Algorithms: DP",
    what: "The two properties that make DP work. Optimal substructure: the best answer to the whole is built from best answers to smaller pieces. Overlapping subproblems: the recursion visits the same smaller pieces many times.",
    why: "This pair is the DP recognition test. Overlap without optimal substructure → caching helps but no recurrence exists. Optimal substructure without overlap → just use divide & conquer (mergesort). Both present → DP. Saying this check out loud is instant structure points.",
    alt: "Greedy (optimal substructure + a provable 'local choice is safe' property — stronger requirement, cheaper algorithm)." },
  "srtbot": { name: "SRTBOT (Erik Demaine, MIT 6.006)", category: "Algorithms: DP",
    what: "MIT's framework for designing any DP: Subproblems, Relation (recurrence), Topological order, Base cases, Original problem (where's the final answer?), Time (= #subproblems × work per relation).",
    why: "The most rigorous 'how do I even start?' scaffold in existence — from Demaine's MIT 6.006 lectures (free on OCW/YouTube, legendary for DP intuition). This deck's 5-step recipe is SRTBOT with friendlier words.",
    alt: "Informal 'define state → recurrence → base case' folklore (same idea, less complete — SRTBOT's O and T steps catch the bugs the folklore misses)." },
  "dp-complexity": { name: "DP complexity formula", category: "Algorithms: DP",
    what: "Time = (number of distinct states) × (work per transition). Space = number of states you must keep alive at once (often reducible to one row or two variables).",
    why: "Answers 'what's the complexity?' before you've written a line: 1-D state with O(1) transition → O(n); n×m table with O(1) transition → O(nm); coin change → O(amount × coins). Stating this formula up front is the cleanest complexity answer available in a coding interview.",
    alt: "Counting operations after the fact (error-prone); recursion-tree analysis (needed only for the NAIVE version, to show why DP is required)." },

  // ---------- ML fundamentals ----------
  "l1-l2-loss": { name: "ℓ2 vs ℓ1 loss (mean vs median)", category: "ML Fundamentals",
    what: "Squared error ℓ2=(y−ŷ)² vs absolute error ℓ1=|y−ŷ|. The population-optimal prediction differs: under ℓ2 it's the conditional MEAN E[Y|X=x]; under ℓ1 it's the conditional MEDIAN.",
    why: "The one-line reason ℓ1 is 'robust': medians shrug at outliers, means chase them. So heavy-tailed targets / outlier-prone labels → ℓ1 (or Huber, the compromise). Also the flashcard caveat worth repeating: a numerical class code is NOT a regression target — logistic regression is a classifier.",
    alt: "Huber loss (ℓ2 near zero, ℓ1 in the tails — differentiable AND robust), quantile loss (any percentile, not just the median)." },
  "supervised": { name: "Supervised vs unsupervised", category: "ML Fundamentals",
    what: "Supervised: learn f(x)→y from labeled pairs (classification, regression). Unsupervised: find structure without labels (clustering: k-means; dimensionality reduction: PCA; density estimation).",
    why: "The modern twist interviewers like: self-supervised learning (next-token prediction, contrastive) manufactures labels from the data itself — it's how LLMs turned 'unlabeled internet' into supervised-scale signal.",
    alt: "Semi-supervised (few labels + many unlabeled), reinforcement learning (reward instead of labels), weak supervision (noisy programmatic labels)." },
  "bias-variance": { name: "Bias-variance tradeoff", category: "ML Fundamentals",
    what: "Expected error = bias² + variance + irreducible noise. Bias: model too simple to fit the truth (underfitting). Variance: model so flexible it fits the sampling noise (overfitting).",
    why: "The classic lever: model capacity trades bias for variance. The senior twist: deep learning complicates the story — 'double descent' shows test error can fall AGAIN past the interpolation point, so the classical U-curve isn't the whole truth (Belkin et al., 2019).",
    alt: "Diagnose with learning curves: high train AND val error → bias; low train, high val → variance. Fixes: more data/regularization for variance, more capacity/features for bias." },
  "overfitting": { name: "Overfitting & regularization", category: "ML Fundamentals",
    what: "Model memorizes training noise; train error falls while validation error rises. Toolkit: L2 (weight decay — smooth shrinkage), L1 (sparsity — feature selection), dropout, early stopping, data augmentation, and more data.",
    why: "The interview answer is the DIAGNOSIS protocol, not the definition: always hold out a validation set, watch the train/val gap, use cross-validation when data is small. Bonus points: early stopping IS implicit regularization; L2 = Gaussian prior, L1 = Laplace prior (MAP view).",
    alt: "Underfitting (the opposite failure), label leakage (looks like great validation but isn't — the sneakiest production bug: features that encode the answer)." },
  "logreg": { name: "Linear / logistic regression", category: "ML Fundamentals",
    what: "Linear: y = wᵀx + b with squared loss (closed form or GD). Logistic: squash wᵀx through a sigmoid → probability, trained with cross-entropy (no closed form; convex, so GD finds the global optimum).",
    why: "Probe magnets: 'why not squared loss for classification?' (non-convex with sigmoid + vanishing gradients at confident wrong answers; cross-entropy's gradient is just (p−y)·x). Logistic regression is also the final layer of every neural classifier — softmax is its multiclass form.",
    alt: "GLMs (the general family), naive Bayes (generative counterpart), a single neuron (it literally is one)." },
  "trees": { name: "Decision trees → ensembles", category: "ML Fundamentals",
    what: "Trees: greedy axis-aligned splits maximizing purity gain (Gini/entropy). Alone they overfit wildly → ensemble them: bagging (Random Forest — many trees on bootstrap samples, averaged) or boosting (XGBoost/LightGBM — sequential trees fitting the residuals).",
    why: "Bagging cuts VARIANCE, boosting cuts BIAS — mapping the two ensemble families onto the bias-variance axes is the exam answer. And the production fact: gradient-boosted trees still beat deep learning on most tabular data (no feature scaling, handles missing values, interpretable-ish).",
    alt: "Deep learning for tabular (usually loses), linear models (when interpretability law applies), CatBoost (categorical-heavy data)." },
  "svm": { name: "SVM & the kernel trick", category: "ML Fundamentals",
    what: "Find the hyperplane maximizing the margin to the nearest points (the support vectors — only they matter). Kernel trick: the optimization uses only dot products x·x′, so swap in k(x,x′) = φ(x)·φ(x′) and you've trained in a huge implicit feature space without ever computing φ.",
    why: "'Maximum margin' and 'only support vectors define the boundary' are the two phrases to say. RBF kernel = infinite-dimensional feature space. Why they faded: O(n²)-ish training doesn't scale past ~10⁵ samples — deep nets and GBDTs took the throne. Hinge loss links them to modern margin-based losses.",
    alt: "Logistic regression (probabilistic, scales better), GBDTs (tabular king), neural nets (learn features instead of kerneling them)." },
  "cnn": { name: "CNNs", category: "ML Fundamentals",
    what: "Convolutional layers slide shared filters over the input: local receptive fields + weight sharing + pooling → translation-equivariant feature hierarchies (edges → textures → parts → objects).",
    why: "The inductive-bias story is the interview answer: convolution bakes 'nearby pixels relate, patterns repeat anywhere' into the architecture, slashing parameters vs dense layers (a 3×3 conv kernel is 9 weights wherever it's applied). Milestones: LeNet → AlexNet (2012, the deep learning detonator) → ResNet (skip connections fix vanishing gradients).",
    alt: "Vision Transformers (less inductive bias, more data hunger — ViT beats CNNs only past ~100M images), classical CV features (SIFT/HOG — what AlexNet obsoleted)." },
  "rnn": { name: "RNNs / LSTMs", category: "ML Fundamentals",
    what: "Process sequences by carrying a hidden state: h_t = f(h_{t−1}, x_t). Vanilla RNNs suffer vanishing/exploding gradients through time; LSTMs/GRUs fix it with gated additive cell states.",
    why: "Know the failure and the fix: backprop-through-time multiplies Jacobians → gradients vanish (or explode; clip them). LSTM's cell state is an additive highway — the same trick as ResNet skips. And the segue interviewers want: RNNs process sequentially (O(n) serial steps, no parallelism) — attention removed the recurrence, which is literally why Transformers won the hardware lottery.",
    alt: "Transformers (parallel, longer range), temporal CNNs/WaveNet (dilated convs), state-space models (Mamba — recurrence returns, but linear and parallelizable)." },

  // ---------- Numerics ----------
  "bf16": { name: "BF16", category: "Numerics",
    what: "bfloat16: FP32's 8-bit exponent with a truncated 7-bit mantissa.",
    why: "Invented at Google Brain for TPUs — same dynamic range as FP32, so no loss-scaling gymnastics that FP16 needs. Now the default training dtype everywhere.",
    alt: "FP16 (more precision, less range, needs loss scaling), TF32 (NVIDIA's 19-bit compromise), FP8 (Hopper Transformer Engine)." },
  "amdahl": { name: "Amdahl's Law", category: "Theory",
    what: "Speedup ≤ 1 / (s + p/N): the serial fraction s caps parallel speedup no matter how many processors.",
    why: "The pipeline bubble IS an Amdahl serial fraction. Counter with Gustafson's Law: at scale you grow the problem instead of shrinking the time.",
    alt: "Gustafson's Law (scaled speedup), roofline model (the memory-side analog)." },
  "roofline": { name: "Roofline model", category: "Theory",
    what: "Plot attainable FLOP/s vs arithmetic intensity (FLOPs/byte): performance is min(peak compute, bandwidth × intensity).",
    why: "One picture that tells you whether to optimize math or memory. From Berkeley (Williams, Waterman & Patterson — yes, THAT Patterson, who also co-authored the TPU papers).",
    alt: "Horace He's three-regime taxonomy: compute-bound, memory-bound, overhead-bound." },
};
if (typeof module !== "undefined") module.exports = NAMEDROPS;
